# This file takes an output file (out.txt) and extracts the traces regarding a specific address, then plot them in a graph.
# the output file is generated by the gem5 simulator.
import re
from loguru import logger
from plantuml import PlantUML
import matplotlib.pyplot as plt
import matplotlib.image as mpimg
import subprocess
import argparse
def extract_trace_lines(tracefile, addrs:list):
    color_arr = ["red", "green", "blue", "yellow", "magenta", "cyan"]
    assert len(addrs) <= len(color_arr), "too many addresses to trace"
    addr_list_flat_or = "|".join(addrs)
    # regex to match the relavent addr is "L.*Cache.*0x(addr_list_flat_or)"

    addr_level_controller_map = {}

    # open file and check each line against the regex
    with open(tracefile, 'r') as f:
        # read all lines
        lines = f.readlines()
        for line in lines:
            # match the line against the regex
            #                         1       2         3            4         5        6              7
            regex = re.search(rf'\s*(\d+)\s*(\d+)\s*L(\d+)Cache\s*([^\s]*)\s*([^\s]*)>([^\s]*)\s*\[0x({addr_list_flat_or}),', line)
            if regex:
                timestamp = int(regex.group(1))
                controller_id = int(regex.group(2))
                controller_level = str(regex.group(3))
                controller = f"L{controller_level}Cache" + str(controller_id)
                
                event = str(regex.group(4))
                from_state = str(regex.group(5))
                to_state = str(regex.group(6))
                addr = str(regex.group(7))

                if addr not in addr_level_controller_map: addr_level_controller_map[addr] = {}
                if controller_level not in addr_level_controller_map[addr]: addr_level_controller_map[addr][controller_level] = {}
                if controller_id not in addr_level_controller_map[addr][controller_level]:
                    addr_level_controller_map[addr][controller_level][controller_id] = []
                addr_level_controller_map[addr][controller_level][controller_id].append((timestamp, event, from_state, to_state))

                color_str = color_arr[addrs.index(addr)]
                # logger.opt(ansi=True).info(f"<{color_str}>Tick {timestamp} {controller}@{addr} {from_state}--{event}-->{to_state}</{color_str}>")
            
            # functional write example:
            #17407000: system.caches.controllers1: MESI_Two_Level-L2cache.sm:525: functionalWrite@0x35900: DataBlk=[ 0x4c 0x69 0x6e 0x75 0x78 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x20 0xea 0xff 0xff 0xff 0x7f 0x0 0x0 0x40 0xeb 0xff 0xff 0xff 0x7f 0x0 0x0 0x10 0xea 0xff 0xff 0xff 0x7f 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 ] (56082ba7b1c0), DataBlk_phy=[ 0x4c 0x69 0x6e 0x75 0x78 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x20 0xea 0xff 0xff 0xff 0x7f 0x0 0x0 0x40 0xeb 0xff 0xff 0xff 0x7f 0x0 0x0 0x10 0xea 0xff 0xff 0xff 0x7f 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 0x0 ] (56082ba7a880)
            function_wr = re.search(rf'\s*(\d+): system.caches.controllers(\d+):.*functionalWrite@0x({addr_list_flat_or})', line)
            if function_wr:
                timestamp = int(function_wr.group(1))
                controller_id = int(function_wr.group(2))
                controller_id = 9999
                addr = str(function_wr.group(3))
                if addr not in addr_level_controller_map: addr_level_controller_map[addr] = {}
                if "2" not in addr_level_controller_map[addr]: addr_level_controller_map[addr][2] = {}
                if controller_id not in addr_level_controller_map[addr]["2"]: addr_level_controller_map[addr]["2"][controller_id] = []
                addr_level_controller_map[addr]["2"][controller_id].append((timestamp, "functionalWrite", "", ""))
                # logger.info(f"functionalWrite@0x{addr} at {timestamp} {controller}")


        return addr_level_controller_map


def report(addr_level_controller_map):
    for addr in addr_level_controller_map:
        logger.info(f"addr {addr} has {len(addr_level_controller_map[addr])} levels controllers: {addr_level_controller_map[addr].keys()}")
        for level in addr_level_controller_map[addr]:
            logger.info(f"  level {level} has {len(addr_level_controller_map[addr][level])} controllers: {addr_level_controller_map[addr][level].keys()}")
            for controller_id in addr_level_controller_map[addr][level]:
                arr_tuple = addr_level_controller_map[addr][level][controller_id]
                logger.info(f"    controller {controller_id} has {len(arr_tuple)} transitions")
                # logger.info(f"    controller {controller_id} at {timestamp} {from_state}--{event}-->{to_state}")


def convert_map_to_plantuml(addr_level_controller_map):
    uml_string = "@startuml\n"
    uml_string += "autonumber\n"
    uml_string += "!pragma teoz true\n"
    uml_string += "skinparam SequenceGroupHeaderLineStyle 3\nskinparam SequenceGroupHeaderLineColor silver\n"

    # sort every transition based on timestamp
    all_transitions = []
    for addr, level_controller_map in addr_level_controller_map.items():
        for level, controller_map in level_controller_map.items():
            for controller_id, transitions in controller_map.items():
                # print(transitions)
                for transition in transitions: all_transitions.append(transition)
    all_transitions.sort(key=lambda x: x[0])  # Sort transitions by timestamp
    # print(all_transitions)
    for transition in all_transitions:
        timestamp, event, from_state, to_state = transition
        uml_string += f"participant {timestamp}\n"

    for addr, level_controller_map in addr_level_controller_map.items():
        uml_string += f"== {addr} ==\n"
        for level, controller_map in level_controller_map.items():
            if level == "1": 
                uml_string += "skinparam SequenceGroupBodyBackgroundColor #F4F4D5\nskinparam SequenceGroupBackgroundColor #DAE1AC\n"
            else:
                uml_string += "skinparam SequenceGroupBodyBackgroundColor #D3E2FA\nskinparam SequenceGroupBackgroundColor #B2CCF9\n"
            for controller_id, transitions in controller_map.items():
                transitions.sort(key=lambda x: x[0])  # Sort transitions by timestamp
                uml_string += f"group L{level}Cache{controller_id} @{addr}\n"
                prev_timestamp = 0
                prev_to_state = ""
                prev_from_state = ""
                prev_event = ""
                for transition in transitions:
                    timestamp, event, from_state, to_state = transition
                    if timestamp == prev_timestamp and from_state == prev_from_state \
                        and event == prev_event and to_state == prev_to_state: 
                        continue

                    if prev_to_state == to_state: 
                        state_substring = f""
                        arrow_string = f"->"
                    else: 
                        state_substring = f"\\n{to_state}"
                        arrow_string = f"-[#red]>"

                    if not from_state == prev_to_state and not prev_to_state == "":
                        logger.debug(f"from_state {from_state} != prev_to_state {prev_to_state}")
                        arrow_string += "x "
                        state_substring += "<&star>"

                    if prev_timestamp != timestamp: uml_string += f"& "
                    uml_string += f"{timestamp}{arrow_string}{timestamp}: {event}{state_substring}\n"
                    prev_timestamp = timestamp
                    prev_to_state = to_state
                    prev_from_state = from_state
                    prev_event = event
                    # break
                uml_string += f"end\n"
    uml_string += "@enduml"
    # print(uml_string)
    return uml_string



# main function
if __name__ == "__main__":

    parser = argparse.ArgumentParser(description="config.")
    parser.add_argument(
        "--addrs",
        type=str,
        required=True,
        help="addr in hex",
        nargs='+',
    )
    parser.add_argument(
        "--path",
        type=str,
        required=True,
        help="path to out file (relative to gem5 root))",
    )
    args = parser.parse_args()

    addr_level_controller_map = extract_trace_lines(args.path, args.addrs)
    # addr_level_controller_map = extract_trace_lines("m5out/m5out_randtester/MyMSI_NINE_XOR_NOBDI_MAP/core4/freq5/ck1000000/out.txt", ["36c0"])
    report(addr_level_controller_map)
    # Create PlantUML object
    p = PlantUML(url='http://www.plantuml.com/plantuml/png/')

    # Convert map to PlantUML string
    uml_string = convert_map_to_plantuml(addr_level_controller_map)

    # Generate diagram
    with open('diagram.txt', 'w') as f:
        f.write(uml_string)
    
    # run this command to render pdf: java -jar /home/zhewen/repo/condor/uml/plantuml.jar -tpdf diagram.txt
    from os.path import expanduser
